    _q(96, "A", 1, "integrals", "∫((x³ − x² + x − 1)/(x² + 1))dx = (a) x²/2 − x + C (b) x − x²/2 + C (c) 1 − x + C (d) x²/2 + x + C"),
    _q(97, "A", 1, "integrals", "∫e^(−7x)dx = (a) −7e^(−7x) + C (b) (−1/7)e^(−7x) + C (c) (1/7)e^(−7x) + C (d) (−1/7)e^(7x) + C"),
